/*
 PLAN:
 1. Composition: vertical loop column of 6 image plates at x=+0.9 (right of frame), headline "Inside the atelier" pinned left at [-1.6,1.9,0], focused-plate caption at x=-1.6; graded backdrop plane 7x6 at z=-2.5.
 2. Light rig (rig-gallery-soft): key directional #fff8f0 1.9 @ [0.8,3.4,2]; hemisphere fill #f2eee8 0.65; rim directional #ffffff 0.8 @ [0.4,1.8,-2.8]; plus node-local red accent strip (emissive 1.4) on focused plate.
 3. Materials: plates MeshPhysicalNodeMaterial map/rough 0.6/metal 0.1/clearcoat 0.1 with TSL tint variants + baked vignette; machined ink #16161d bevel frames rough 0.5/metal 0.5; TSL gradient backdrop.
 4. Motion: scroll drives column y with damped inertia (0.12) mod 9.0, weighted-settle 900ms; focused plate scales 1.0->1.06 350ms; caption fade-up; fly-through primitive on scroll (depthUnits 2.5); idle slow drift only.
 5. Focal element: the plate nearest y=0 — brightest read via accent strip, scale-up, and its caption; everything else graded below it.
*/
import { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, DirectionalLight, HemisphereLight, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, Color, SRGBColorSpace } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, float, texture as tslTexture, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.name = 'loop-column-gallery';

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {};
  const C_BG = colors.background ?? '#0b0b10';
  const C_SURFACE = colors.surface ?? '#14141a';
  const C_INK = colors.ink ?? '#16161d';
  const C_PAPER = colors.paper ?? '#e8ecf2';
  const C_ACCENT = colors.accent ?? '#ff2a38';
  const stops = colors.gradientStops ?? [{ at: 0, hex: C_BG }, { at: 1, hex: C_SURFACE }];

  const geometries = [];
  const materials = [];
  const timelines = [];
  const primHandles = [];
  let sharedTexture = null;

  // ---------- backdropStage: gradient stage plane (color.background / color.surface / color.gradient) ----------
  const bgGeo = new PlaneGeometry(7, 6);
  geometries.push(bgGeo);
  const bgMat = new MeshBasicNodeMaterial();
  const gTop = tslColor(new Color(stops[stops.length - 1].hex));
  const gBot = tslColor(new Color(stops[0].hex));
  const vy = uv().y;
  // vertical gradient + soft horizontal falloff so the stage never reads flat
  const horiz = smoothstep(float(0.0), float(0.45), uv().x.sub(0.5).abs().oneMinus());
  bgMat.colorNode = mix(gBot, gTop, vy).mul(mix(float(0.75), float(1.0), horiz));
  materials.push(bgMat);
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- lightRig: rig-gallery-soft ----------
  const key = new DirectionalLight(new Color('#fff8f0'), 1.9);
  key.position.set(0.8, 3.4, 2);
  key.target.position.set(0, 0.5, 0);
  root.add(key, key.target);
  const fill = new HemisphereLight(new Color('#f2eee8'), new Color(C_BG), 0.65);
  root.add(fill);
  const rim = new DirectionalLight(new Color('#ffffff'), 0.8);
  rim.position.set(0.4, 1.8, -2.8);
  rim.target.position.set(0, 0.6, 0);
  root.add(rim, rim.target);

  // ---------- column: 6 plates, pitch 1.5, loop 9.0, x=+0.9 ----------
  const COLUMN_X = 0.9;
  const PITCH = 1.5;
  const LOOP = 9.0;
  const PLATE_W = 1.9, PLATE_H = 1.2;
  const column = new Group();
  column.position.x = COLUMN_X;
  root.add(column);

  const captionsSpec = (config.textContent ?? config.intent?.visualSpec?.textContent ?? [])
    .filter((t) => t.role === 'caption');
  const headlineItem = (config.textContent ?? config.intent?.visualSpec?.textContent ?? [])
    .find((t) => t.role === 'headline');

  // distinct crop offsets + subtle filmic tint variants per plate (five variants + base)
  const variants = [
    { off: [0.0, 0.0], scale: 1.0, tint: [1.0, 1.0, 1.0] },
    { off: [0.25, 0.1], scale: 0.7, tint: [1.02, 0.98, 0.95] },
    { off: [0.1, 0.35], scale: 0.6, tint: [0.95, 0.97, 1.0] },
    { off: [0.35, 0.25], scale: 0.65, tint: [1.03, 1.0, 0.94] },
    { off: [0.05, 0.2], scale: 0.8, tint: [0.97, 0.99, 1.0] },
    { off: [0.2, 0.05], scale: 0.75, tint: [1.0, 0.96, 0.96] },
  ];

  const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H);
  geometries.push(plateGeo);
  const bevelGeo = new BoxGeometry(PLATE_W + 0.06, PLATE_H + 0.06, 0.03);
  geometries.push(bevelGeo);

  // bevelFrames material: machined ink with brushed highlight (color.ink)
  const bevelMat = new MeshStandardNodeMaterial({ roughness: 0.5, metalness: 0.5 });
  bevelMat.colorNode = tslColor(new Color(C_INK)).add(
    smoothstep(float(0.94), float(1.0), uv().x).mul(0.08)
  );
  materials.push(bevelMat);

  const plates = [];
  const plateMats = [];

  for (let i = 0; i < 6; i++) {
    const v = variants[i % variants.length];
    const plateGroup = new Group();

    const mat = new MeshPhysicalNodeMaterial({ roughness: 0.6, metalness: 0.1, clearcoat: 0.1 });
    // filmic-graded crop variant + baked vignette; warm placeholder until texture arrives
    const u = uv();
    const cropUv = u.mul(float(v.scale)).add(vec3(v.off[0], v.off[1], 0).xy);
    const d = u.sub(0.5).length();
    const vignette = smoothstep(float(0.78), float(0.30), d).mul(0.55).add(0.45);
    const tint = vec3(v.tint[0], v.tint[1], v.tint[2]);
    const placeholder = mix(tslColor(new Color(C_SURFACE)).mul(1.6), tslColor(new Color('#3a3a44')), u.y);
    mat.colorNode = placeholder.mul(tint).mul(vignette);
    plateMats.push({ mat, cropUv, tint, vignette });
    materials.push(mat);

    const bevel = new Mesh(bevelGeo, bevelMat);
    bevel.position.z = -0.02;
    plateGroup.add(bevel);

    const plate = new Mesh(plateGeo, mat);
    plateGroup.add(plate);

    // accent strip on left edge (color.accent), hidden unless focused
    const stripGeo = new PlaneGeometry(0.03, PLATE_H);
    geometries.push(stripGeo);
    const stripMat = new MeshStandardNodeMaterial({ roughness: 0.4, metalness: 0.2 });
    stripMat.colorNode = tslColor(new Color(C_ACCENT));
    stripMat.emissiveNode = tslColor(new Color(C_ACCENT)).mul(1.4);
    materials.push(stripMat);
    const strip = new Mesh(stripGeo, stripMat);
    strip.position.set(-PLATE_W / 2 - 0.045, 0, 0.005);
    strip.visible = false;
    plateGroup.add(strip);

    plateGroup.position.y = 2.5 - i * PITCH; // base slot; wrapped in update
    plateGroup.userData.baseIndex = i;
    column.add(plateGroup);
    plates.push({ group: plateGroup, strip, focused: false });
  }

  // shared texture load — one URL, distinct crops per plate via TSL uv offsets
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      sharedTexture = tex;
      tex.colorSpace = SRGBColorSpace;
      for (const p of plateMats) {
        p.mat.colorNode = tslTexture(tex, p.cropUv).rgb.mul(p.tint).mul(p.vignette);
        p.mat.needsUpdate = true;
      }
    });
  }

  // ---------- contact shadow under column base ----------
  const shadowGeo = new CircleGeometry(1.4, 32);
  geometries.push(shadowGeo);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  const sd = uv().sub(0.5).length().mul(2.0);
  shadowMat.colorNode = vec3(0, 0, 0);
  shadowMat.opacityNode = smoothstep(float(1.0), float(0.2), sd).mul(0.5);
  materials.push(shadowMat);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(COLUMN_X, -2.6, 0.2);
  root.add(shadow);

  // ---------- headlineText: pinned at [-1.6, 1.9, 0] (text.headline.0, color.paper) ----------
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: headlineItem.typography?.fontSize ?? 68,
      color: C_PAPER,
      align: 'left',
      maxWidthPx: 520,
    });
    headline.position.set(-1.6, 1.9, 0);
    root.add(headline);
    const tl = gsap.timeline();
    tl.from(headline.position, { y: 1.5, duration: 0.7, ease: 'power3.out' });
    timelines.push(tl);
  }

  // ---------- captionSlot: focused-plate caption fading up at x=-1.6 (text.caption.1..6) ----------
  const captionSlot = new Group();
  captionSlot.position.set(-1.6, 0, 0);
  root.add(captionSlot);
  const captionMeshes = captionsSpec.map((item) => {
    const m = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 18,
      color: C_PAPER,
      align: 'left',
      letterSpacingPx: 1.6, // ~0.08em on 18px caps
    });
    m.visible = false;
    captionSlot.add(m);
    return m;
  });
  let currentCaption = -1;

  // ---------- scrollLoop: weighted inertia column scroll, mod 9.0 ----------
  const scrollState = { target: 0, current: 0 };
  const DAMPING = 0.12;
  const settleEase = 'power4.out'; // cubic-bezier(0.165,0.84,0.44,1) equivalent weighted-settle
  let settleTween = null;

  function wrapAndFocus() {
    let bestIdx = -1;
    let bestDist = Infinity;
    for (const p of plates) {
      const base = 2.5 - p.group.userData.baseIndex * PITCH;
      let y = ((base + scrollState.current) % LOOP + LOOP) % LOOP; // 0..9
      y -= 4.5; // center loop around 0 -> -4.5..4.5
      p.group.position.y = y;
      const dist = Math.abs(y);
      if (dist < bestDist) { bestDist = dist; bestIdx = plates.indexOf(p); }
    }
    // focus handling
    plates.forEach((p, idx) => {
      const shouldFocus = idx === bestIdx;
      if (shouldFocus && !p.focused) {
        p.focused = true;
        p.strip.visible = true;
        const tl = gsap.timeline();
        tl.to(p.group.scale, { x: 1.06, y: 1.06, z: 1.06, duration: 0.35, ease: 'power2.out' });
        timelines.push(tl);
      } else if (!shouldFocus && p.focused) {
        p.focused = false;
        p.strip.visible = false;
        const tl = gsap.timeline();
        tl.to(p.group.scale, { x: 1, y: 1, z: 1, duration: 0.35, ease: 'power2.out' });
        timelines.push(tl);
      }
    });
    // caption swap: caption index follows the focused plate's base index
    if (bestIdx >= 0) {
      const capIdx = plates[bestIdx].group.userData.baseIndex % captionMeshes.length;
      if (capIdx !== currentCaption && captionMeshes[capIdx]) {
        if (currentCaption >= 0 && captionMeshes[currentCaption]) {
          captionMeshes[currentCaption].visible = false;
        }
        currentCaption = capIdx;
        const cm = captionMeshes[capIdx];
        cm.visible = true;
        cm.position.set(0, -0.2, 0);
        const tl = gsap.timeline();
        tl.to(cm.position, { y: 0, duration: 0.5, ease: 'power2.out' });
        timelines.push(tl);
      }
    }
  }
  wrapAndFocus();

  // damped inertia driver
  const inertiaTicker = () => {
    const delta = scrollState.target - scrollState.current;
    if (Math.abs(delta) > 0.0005) {
      scrollState.current += delta * DAMPING;
      wrapAndFocus();
    }
  };
  gsap.ticker.add(inertiaTicker);

  // idle: ONE slow drift on the column loop
  const idleTl = gsap.timeline({ repeat: -1 });
  idleTl.to(scrollState, {
    target: `+=${LOOP}`,
    duration: 60,
    ease: 'none',
    onUpdate: () => {}, // inertia ticker consumes target
  });
  timelines.push(idleTl);

  // ---------- primitives: apply EVERY config.cinematicPrimitives (fly-through) ----------
  for (const prim of config.cinematicPrimitives ?? []) {
    const handle = ctx.primitives[prim.name](root, prim.params);
    if (handle) primHandles.push(handle);
  }

  // ---------- handlers: scroll drives column with weighted-settle ----------
  root.userData.handlers = {
    scroll: (e) => {
      const d = (e && (e.deltaY ?? e.delta ?? 0)) || 0;
      idleTl.pause();
      scrollState.target += (d / 100) * 1.5; // 1.5 units per viewport scroll step
      if (settleTween) settleTween.kill();
      settleTween = gsap.to(scrollState, {
        target: Math.round(scrollState.target / PITCH) * PITCH,
        duration: 0.9,
        ease: settleEase,
        delay: 0.15,
        onComplete: () => idleTl.resume(),
      });
      timelines.push(settleTween);
    },
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    gsap.ticker.remove(inertiaTicker);
    for (const tl of timelines) tl.kill();
    if (settleTween) settleTween.kill();
    for (const h of primHandles) h.cleanup && h.cleanup();
    for (const g of geometries) g.dispose();
    for (const m of materials) m.dispose();
    if (sharedTexture) sharedTexture.dispose();
  };

  return root;
}

/* @spec-manifest
{"elements":[
{"id":"text.headline.0","where":"headlineText","how":"fontAtlas headline pinned at [-1.6,1.9,0]"},
{"id":"text.caption.1","where":"captionSlot","how":"caption mesh in focused-plate caption slot"},
{"id":"text.caption.2","where":"captionSlot","how":"caption mesh in focused-plate caption slot"},
{"id":"text.caption.3","where":"captionSlot","how":"caption mesh in focused-plate caption slot"},
{"id":"text.caption.4","where":"captionSlot","how":"caption mesh in focused-plate caption slot"},
{"id":"text.caption.5","where":"captionSlot","how":"caption mesh in focused-plate caption slot"},
{"id":"text.caption.6","where":"captionSlot","how":"caption mesh in focused-plate caption slot"},
{"id":"color.background","where":"backdropStage","how":"gradient bottom stop #0b0b10"},
{"id":"color.surface","where":"backdropStage","how":"gradient top stop and plate placeholder"},
{"id":"color.ink","where":"bevelFrames","how":"machined ink bevel material colorNode"},
{"id":"color.paper","where":"headlineText","how":"headline and caption text color"},
{"id":"color.accent","where":"column","how":"emissive 1.4 accent strip on focused plate"},
{"id":"color.gradient","where":"backdropStage","how":"2-stop vertical TSL gradient"},
{"id":"effects.spec","where":"column","how":"six 1.9x1.2 plates, pitch 1.5, loop 9, damped scroll"},
{"id":"primitive.fly-through","where":"primitives","how":"ctx.primitives fly-through applied to root"}
]}
*/
